const fs=require('fs');const path=require('path');const {execFile}=require('child_process');const {promisify}=require('util');
let timer,running=false,attempt=0;
exports.load=()=>{const config=JSON.parse(fs.readFileSync(path.join(__dirname,'config.json'),'utf8'));timer=setInterval(async()=>{if(running)return;running=true;try{const original=await Editor.Message.request('scene','execute-scene-script',{name:'p2-qualification',method:'createFixture',args:[config.dir]});const child=await promisify(execFile)(config.node,[config.restore,config.project,config.dir],{timeout:30000});const verification=await Editor.Message.request('scene','execute-scene-script',{name:'p2-qualification',method:'verify',args:[config.dir]});fs.writeFileSync(config.report,JSON.stringify({status:'PASS',creator:Editor.App.version,original,verification,codec:child.stdout,timestamp:new Date().toISOString()},null,2));clearInterval(timer);}catch(error){attempt++;if(attempt>=60){fs.writeFileSync(config.report,JSON.stringify({status:'FAIL',error:String(error.stack||error)},null,2));clearInterval(timer);}else{fs.writeFileSync(config.progress,JSON.stringify({attempt,error:String(error.message||error)}));}}finally{running=false;}},2000);};
exports.unload=()=>clearInterval(timer);
